"use client";
import { formatDisplayDate } from "@/lib/logic/displayDate";
import { useEffect,useMemo,useState } from "react";
import { ChevronLeft,ChevronRight,Globe2,Search,Trophy } from "lucide-react";
import { getInternationalLeaders,INTERNATIONAL_TEAMS,internationalProfileName,internationalProgrammePreview,internationalTeamName,type InternationalCareerState,type InternationalFixture,type InternationalPlayerProfile,type InternationalPlayerStats,type InternationalSeries } from "@/lib/logic/international";
import { useGameStore } from "@/lib/store/gameStore";
import type { CareerStaffContract } from "@/lib/logic/staffContracts";

type View="overview"|"fixtures"|"teams"|"rankings"|"stats"|"worldcup"|"history";
const VIEWS:View[]=["overview","fixtures","teams","rankings","stats","worldcup","history"];
const CORE=new Set(["IND","AUS","ENG","SA","NZ","WI","SL"]);
const bowler=(p?:InternationalPlayerProfile)=>p?.role==="Pace Bowler"||p?.role==="Spin Bowler"||p?.role==="All-Rounder";
const team=(id:string)=>INTERNATIONAL_TEAMS.find(t=>t.id===id);
const score=(s?:[number,number])=>s?`${s[0]}/${s[1]}`:"—";
const overs=(b:number)=>`${Math.floor(b/6)}.${b%6}`;

export default function InternationalPage({career,onOpenFullPlayer}:{career:InternationalCareerState;onOpenFullPlayer?:(id:string)=>void}){
 const [view,setView]=useState<View>("overview"),[teamId,setTeamId]=useState<string|null>(null),[match,setMatch]=useState<InternationalFixture|null>(null),[light,setLight]=useState<string|null>(null),[query,setQuery]=useState("");
 const preview=useMemo(()=>internationalProgrammePreview(career.season+1),[career.season]);
 const programmeCareer=useMemo<InternationalCareerState>(()=>({...career,series:[...career.series,...preview.series],fixtures:[...career.fixtures,...preview.fixtures]}),[career,preview]);
 const played=useMemo(()=>career.fixtures.filter(f=>f.played).sort((a,b)=>b.date.localeCompare(a.date)),[career.fixtures]);
 const upcoming=useMemo(()=>programmeCareer.fixtures.filter(f=>!f.played).sort((a,b)=>a.date.localeCompare(b.date)),[programmeCareer.fixtures]);
 const leaders=useMemo(()=>getInternationalLeaders(career),[career]);
 const openPlayer=(id:string)=>{const p=career.profiles[id];if(p?.fullPlayerId&&onOpenFullPlayer)onOpenFullPlayer(p.fullPlayerId);else if(p)setLight(id)};
 const nav=(v:View)=>{setView(v);setTeamId(null)};
 return <div className="mx-auto flex h-full min-h-0 w-full min-w-0 max-w-[1560px] flex-col overflow-hidden p-2 sm:p-3">
  <header className="z-30 shrink-0 overflow-hidden rounded-xl border border-border bg-surface/95 shadow-sm backdrop-blur">
   <div className="flex flex-wrap items-center gap-3 px-3 py-2.5 sm:px-4"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-accent text-white"><Globe2 size={18}/></div><div className="min-w-40 flex-1"><p className="font-space-mono text-[6px] font-bold uppercase tracking-[.2em] text-accent">Global T20 circuit · {career.season}</p><h1 className="font-anton text-xl uppercase">International T20</h1></div><HeadFact label="Next match" value={upcoming[0]?`${internationalTeamName(upcoming[0].teamA)} v ${internationalTeamName(upcoming[0].teamB)}`:"Season complete"}/><label className="relative w-full shrink-0 sm:w-56"><Search className="absolute left-3 top-2 text-text-secondary" size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search teams or players" className="h-8 w-full rounded-lg border border-border bg-bg pl-9 pr-3 text-[9px] outline-none focus:border-accent"/></label></div>
   <nav className="flex overflow-x-auto border-t border-border px-2">{VIEWS.map(v=><button key={v} onClick={()=>nav(v)} className={`relative min-w-max flex-1 px-4 py-2 font-space-mono text-[7px] font-bold uppercase ${view===v?"text-accent":"text-text-secondary"}`}>{v}{view===v&&<span className="absolute inset-x-3 bottom-0 h-0.5 bg-accent"/>}</button>)}</nav>
  </header>
  <main className="mt-3 min-h-0 min-w-0 flex-1 overflow-hidden">{query?<SearchView q={query} career={career} team={id=>{setTeamId(id);setView("teams");setQuery("")}} player={openPlayer}/>:view==="overview"?<Overview career={programmeCareer} played={played} upcoming={upcoming} leaders={leaders} match={setMatch} nav={nav} team={id=>{setTeamId(id);setView("teams")}} player={openPlayer}/>:view==="fixtures"?<Fixtures career={programmeCareer} match={setMatch}/>:view==="teams"?(teamId?<Country career={programmeCareer} id={teamId} back={()=>setTeamId(null)} player={openPlayer} match={setMatch}/>:<Teams career={career} select={setTeamId}/>):view==="rankings"?<Rankings career={career} select={id=>{setTeamId(id);setView("teams")}}/>:view==="stats"?<Stats career={career} player={openPlayer}/>:view==="worldcup"?<WorldCup career={career} match={setMatch}/>:<Archive career={career}/>}</main>
  {match&&<Scorecard fixture={match} career={career} close={()=>setMatch(null)} player={openPlayer}/>} {light&&<LightProfile p={career.profiles[light]} s={career.careerStats[light]} close={()=>setLight(null)}/>} 
 </div>
}

function HeadFact({label,value}:{label:string;value:string}){return <div className="hidden max-w-56 lg:block"><p className="font-space-mono text-[6px] uppercase text-text-secondary">{label}</p><p className="truncate text-[10px] font-bold">{value}</p></div>}
function Panel({children,className=""}:{children:React.ReactNode;className?:string}){return <section className={`rounded-xl border border-border bg-surface ${className}`}>{children}</section>}
function Title({over,title,action}:{over?:string;title:string;action?:React.ReactNode}){return <div className="flex items-end justify-between gap-3"><div>{over&&<p className="font-space-mono text-[7px] font-bold uppercase text-accent">{over}</p>}<h2 className="font-anton text-xl uppercase">{title}</h2></div>{action}</div>}
function Metric({v,l}:{v:string|number;l:string}){return <div className="rounded-lg border border-border bg-bg p-3"><b className="font-anton text-xl">{v}</b><p className="font-space-mono text-[6px] uppercase text-text-secondary">{l}</p></div>}
function Empty({children}:{children:React.ReactNode}){return <div className="grid min-h-24 place-items-center rounded-lg border border-dashed border-border bg-bg text-[10px] text-text-secondary">{children}</div>}
function Pager({page,pages,setPage}:{page:number;pages:number;setPage:(page:number)=>void}){if(pages<=1)return null;return <div className="flex shrink-0 items-center justify-end gap-2"><button disabled={page===0} onClick={()=>setPage(Math.max(0,page-1))} className="grid size-7 place-items-center rounded border border-border disabled:opacity-30"><ChevronLeft size={13}/></button><span className="font-space-mono text-[7px] font-bold uppercase">{page+1} / {pages}</span><button disabled={page>=pages-1} onClick={()=>setPage(Math.min(pages-1,page+1))} className="grid size-7 place-items-center rounded border border-border disabled:opacity-30"><ChevronRight size={13}/></button></div>}

function Overview({career,played,upcoming,leaders,match,nav,team:openTeam,player}:{career:InternationalCareerState;played:InternationalFixture[];upcoming:InternationalFixture[];leaders:ReturnType<typeof getInternationalLeaders>;match:(f:InternationalFixture)=>void;nav:(v:View)=>void;team:(id:string)=>void;player:(id:string)=>void}){const next=upcoming[0],rank=Object.entries(career.rankings).sort((a,b)=>b[1]-a[1]);return <div className="grid h-full min-h-0 grid-cols-12 grid-rows-2 gap-3">
 <Panel className="relative col-span-7 min-h-0 overflow-hidden p-4"><div className="absolute right-0 top-0 h-full w-1/3 bg-gradient-to-l from-accent/10"/><p className="font-space-mono text-[7px] uppercase text-accent">{next?`Next match · ${formatDisplayDate(next.date)}`:"Programme complete"}</p>{next?<><div className="relative mt-3 grid grid-cols-[1fr_auto_1fr] items-center gap-3"><Hero id={next.teamA} right click={()=>openTeam(next.teamA)}/><b className="grid size-10 place-items-center rounded-full border border-border bg-bg font-anton">VS</b><Hero id={next.teamB} click={()=>openTeam(next.teamB)}/></div ><p className="relative mt-3 truncate text-center text-[8px] text-text-secondary">{next.matchNumber} T20I · {next.venue}</p></>:<h2 className="relative mt-6 font-anton text-2xl uppercase">All matches completed</h2>}</Panel>
  <Panel className="col-span-5 flex min-h-0 flex-col overflow-hidden p-4"><div className="shrink-0"><Title over="Live table" title="T20I rankings" action={<Link onClick={()=>nav("rankings")}/>}/></div><div className="mt-2 min-h-0 flex-1 overflow-y-auto pr-1">{rank.map(([id,r],i)=><button key={id} onClick={()=>openTeam(id)} className="grid w-full grid-cols-[1.75rem_minmax(0,1fr)_auto] items-center border-b border-border/60 py-1 text-left text-[9px] hover:bg-accent/5"><span className="font-space-mono text-[8px] text-text-secondary">#{i+1}</span><b className="truncate pr-2">{internationalTeamName(id)}</b><b className="font-space-mono text-accent">{r.toFixed(1)}</b></button>)}</div></Panel>
 <Panel className="col-span-4 min-h-0 overflow-hidden p-4"><Title over="Series centre" title="Active series" action={<Link onClick={()=>nav("fixtures")}/>}/><div className="mt-2 space-y-2">{career.series.filter(s=>!s.completed).slice(0,2).map(s=><SeriesCard key={s.id} s={s} career={career}/>)}</div></Panel>
 <Panel className="col-span-4 min-h-0 overflow-hidden p-4"><Title over="This season" title="Leaders" action={<Link onClick={()=>nav("stats")}/>}/><div className="mt-2 grid grid-cols-2 gap-4"><Leaders title="Runs" rows={leaders.batting.slice(0,4)} career={career} player={player}/><Leaders title="Wickets" rows={leaders.bowling.filter(([id])=>bowler(career.profiles[id])).slice(0,4)} career={career} player={player} bowl/></div></Panel>
 <Panel className="col-span-4 min-h-0 overflow-hidden p-4"><Title over="Results" title="Latest matches"/><div className="mt-2 grid grid-cols-2 gap-2">{played.slice(0,4).map(f=><MatchCard key={f.id} f={f} click={()=>match(f)}/>)}</div></Panel>
 </div>}
function Link({onClick}:{onClick:()=>void}){return <button onClick={onClick} className="text-[8px] font-bold uppercase text-accent">View all</button>}
function Hero({id,right,click}:{id:string;right?:boolean;click:()=>void}){return <button onClick={click} className={right?"min-w-0 text-right":"min-w-0 text-left"}><small className="text-text-secondary">{team(id)?.shortName??id}</small><h2 className="truncate font-anton text-2xl uppercase sm:text-4xl">{internationalTeamName(id)}</h2></button>}
function SeriesCard({s,career}:{s:InternationalSeries;career:InternationalCareerState}){return <div className="rounded-lg border border-border bg-bg p-4"><p className="text-[7px] uppercase text-accent">{s.matchCount}-match series</p><div className="mt-2 flex justify-between gap-2 text-[10px]"><b>{internationalTeamName(s.hostCountry)}</b><strong className="font-anton text-xl">{s.homeWins}–{s.awayWins}</strong><b>{internationalTeamName(s.touringCountry)}</b></div><div className="mt-3 flex gap-1">{s.fixtureIds.map(id=>{const f=career.fixtures.find(x=>x.id===id);return <i key={id} className={`h-1.5 flex-1 rounded ${!f?.played?"bg-border":f.winner===s.hostCountry?"bg-accent":"bg-text-secondary"}`}/>})}</div></div>}
function MatchCard({f,click}:{f:InternationalFixture;click:()=>void}){return <button onClick={click} disabled={!f.played} className="rounded-lg border border-border bg-bg p-3 text-left hover:border-accent disabled:hover:border-border"><div className="flex justify-between text-[6px] uppercase text-text-secondary"><span>{formatDisplayDate(f.date)}</span><span>{f.stage.replaceAll("-"," ")}</span></div>{[[f.teamA,f.scoreA],[f.teamB,f.scoreB]].map(([id,s])=><div key={String(id)} className={`mt-2 flex justify-between text-[10px] ${f.winner===id?"font-bold":""}`}><span>{internationalTeamName(String(id))}</span><span>{score(s as [number,number]|undefined)}</span></div>)}</button>}
function Leaders({title,rows,career,player,bowl=false}:{title:string;rows:Array<[string,InternationalPlayerStats]>;career:InternationalCareerState;player:(id:string)=>void;bowl?:boolean}){return <div><p className="text-[7px] uppercase text-text-secondary">{title}</p>{rows.map(([id,s],i)=><button key={id} onClick={()=>player(id)} className="grid w-full grid-cols-[1rem_1fr_auto] border-b border-border/70 py-2 text-left text-[9px]"><span>{i+1}</span><b className="truncate">{internationalProfileName(career,id)}</b><b className="text-accent">{bowl?s.wickets:s.runs}</b></button>)}</div>}

function Fixtures({career,match}:{career:InternationalCareerState;match:(f:InternationalFixture)=>void}){const [filter,setFilter]=useState("all"),[status,setStatus]=useState("all"),[page,setPage]=useState(0),filtered=career.series.filter(s=>(filter==="all"||s.hostCountry===filter||s.touringCountry===filter)&&s.fixtureIds.some(id=>{const f=career.fixtures.find(x=>x.id===id);return status==="all"||(status==="completed"?f?.played:!f?.played)})),pages=Math.max(1,Math.ceil(filtered.length/3)),safePage=Math.min(page,pages-1);return <div className="flex h-full min-h-0 flex-col gap-3"><Panel className="flex shrink-0 items-center justify-between gap-3 p-4"><Title over={`${career.season} programme`} title="Fixtures and series"/><div className="flex items-center gap-2"><select value={filter} onChange={e=>{setFilter(e.target.value);setPage(0)}} className="rounded border border-border bg-bg px-3 py-2 text-[8px]"><option value="all">All teams</option>{INTERNATIONAL_TEAMS.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select>{["all","upcoming","completed"].map(x=><button key={x} onClick={()=>{setStatus(x);setPage(0)}} className={`rounded border px-3 py-2 text-[7px] uppercase ${status===x?"border-accent bg-accent text-white":"border-border"}`}>{x}</button>)}<Pager page={safePage} pages={pages} setPage={setPage}/></div></Panel><div className="grid min-h-0 flex-1 grid-cols-3 gap-3">{filtered.slice(safePage*3,safePage*3+3).map(s=><SeriesRows key={s.id} s={s} career={career} status={status} match={match}/>)}</div>{!filtered.length&&<Empty>No series match those filters.</Empty>}</div>}
function SeriesRows({s,career,status,match}:{s:InternationalSeries;career:InternationalCareerState;status:string;match:(f:InternationalFixture)=>void}){const rows=s.fixtureIds.map(id=>career.fixtures.find(f=>f.id===id)!).filter(Boolean).filter(f=>status==="all"||(status==="completed"?f.played:!f.played));if(!rows.length)return null;return <Panel className="min-h-0 overflow-hidden"><div className="flex justify-between gap-2 border-b border-border p-4"><div className="min-w-0"><small className="uppercase text-accent">{s.matchCount}-match series</small><h3 className="truncate font-anton text-base uppercase">{internationalTeamName(s.touringCountry)} tour of {internationalTeamName(s.hostCountry)}</h3></div><b className="shrink-0 font-anton text-xl">{s.homeWins}–{s.awayWins}</b></div>{rows.map(f=><button key={f.id} onClick={()=>f.played&&match(f)} className="grid w-full grid-cols-[4.5rem_minmax(0,1fr)_auto] border-b border-border/60 px-4 py-2.5 text-left text-[8px]"><span>{formatDisplayDate(f.date)}</span><b className="truncate">{f.matchNumber} T20I · {f.venue}</b><span className="pl-2">{f.played?`${score(f.scoreA)} · ${score(f.scoreB)}`:"Scheduled"}</span></button>)}</Panel>}

function Teams({career,select}:{career:InternationalCareerState;select:(id:string)=>void}){const [page,setPage]=useState(0),rows=[...INTERNATIONAL_TEAMS].sort((a,b)=>(career.rankings[b.id]??0)-(career.rankings[a.id]??0)),pages=Math.ceil(rows.length/12);return <Panel className="flex h-full min-h-0 flex-col p-4"><div className="flex shrink-0 items-end justify-between"><Title over="27 national programmes" title="Teams"/><Pager page={page} pages={pages} setPage={setPage}/></div><div className="mt-3 grid min-h-0 flex-1 gap-2 overflow-y-auto sm:grid-cols-2 xl:grid-cols-4">{rows.slice(page*12,page*12+12).map((t,index)=>{const state=career.teams[t.id],rating=career.rankings[t.id]??0;return <button key={t.id} onClick={()=>select(t.id)} disabled={!state} className="group min-h-28 rounded-lg border border-border bg-bg p-3 text-left enabled:hover:border-accent disabled:opacity-60"><div className="flex justify-between"><b className="grid size-8 place-items-center rounded bg-[var(--ink)] font-anton text-sm text-white">{t.shortName}</b><span className="text-[8px]">#{page*12+index+1}</span></div><h3 className="mt-2 truncate font-anton text-base uppercase group-enabled:group-hover:text-accent">{t.name}</h3><p className="truncate text-[7px] text-text-secondary">Captain · {state?internationalProfileName(career,state.captainId):"Programme unavailable"}</p><div className="mt-2 flex justify-between border-t border-border pt-2 text-[7px]"><span>{t.core?"Database":"Lightweight"}</span><b>{rating.toFixed(1)}</b></div></button>})}</div></Panel>}

function Country({career,id,back,player,match}:{career:InternationalCareerState;id:string;back:()=>void;player:(id:string)=>void;match:(f:InternationalFixture)=>void}){const staffContracts=useGameStore(state=>state.careerStaff.contracts);const nationalStaff=Object.values(staffContracts).filter(contract=>contract.status==="contracted"&&contract.nationalTeamId===id&&contract.nationalFormat==="t20");const headCoach=nationalStaff.find(contract=>contract.roles.includes("head_coach"));const st=career.teams[id],[tab,setTab]=useState("squad"),[fixturePage,setFixturePage]=useState(0),squad=st.squad.map(x=>career.profiles[x]).filter(Boolean),fixtures=career.fixtures.filter(f=>f.teamA===id||f.teamB===id),fixturePages=Math.max(1,Math.ceil(fixtures.length/9));return <div className="flex h-full min-h-0 flex-col gap-3"><Panel className="shrink-0 overflow-hidden"><div className="flex flex-wrap items-center gap-3 bg-[#16130f] px-3 py-3 text-white dark:bg-[#0f1420] sm:px-4"><button onClick={back} className="flex shrink-0 items-center gap-1 text-[9px] font-bold uppercase text-white/70 hover:text-white"><ChevronLeft size={13}/> All teams</button><div className="min-w-32 flex-1"><small>Rank #{rank(career,id)} · {career.rankings[id].toFixed(1)}</small><h2 className="truncate font-anton text-2xl uppercase">{internationalTeamName(id)}</h2></div><div className="grid w-full grid-cols-2 gap-2 sm:w-auto sm:grid-cols-3"><LeaderBox l="Head coach" n={headCoach?.fullName??"Vacant"}/><LeaderBox l="Captain" n={internationalProfileName(career,st.captainId)}/><LeaderBox l="Vice-captain" n={st.viceCaptainId?internationalProfileName(career,st.viceCaptainId):"—"}/></div></div><div className="flex overflow-x-auto">{["squad","xi","fixtures","stats","staff"].map(x=><button key={x} onClick={()=>setTab(x)} className={`min-w-max flex-1 px-4 py-2.5 text-[9px] font-bold uppercase ${tab===x?"border-b-2 border-accent text-accent":""}`}>{x==="xi"?"Playing XI":x}</button>)}</div></Panel><div className="min-h-0 flex-1 overflow-hidden">{tab==="squad"?<Squad squad={squad} career={career} st={st} player={player}/>:tab==="xi"?<XI career={career} st={st} player={player}/>:tab==="fixtures"?<Panel className="flex h-full min-h-0 flex-col p-4"><div className="flex shrink-0 items-end justify-between"><Title title="Fixtures"/><Pager page={fixturePage} pages={fixturePages} setPage={setFixturePage}/></div><div className="mt-3 grid min-h-0 flex-1 grid-cols-3 grid-rows-3 gap-2">{fixtures.slice(fixturePage*9,fixturePage*9+9).map(f=><MatchCard key={f.id} f={f} click={()=>match(f)}/>)}</div></Panel>:tab==="staff"?<NationalStaffPanel staff={nationalStaff}/>:<CountryStats id={id} career={career} player={player}/>}</div></div>}
function NationalStaffPanel({staff}:{staff:CareerStaffContract[]}){const ordered=[...staff].sort((a,b)=>Number(b.roles.includes("head_coach"))-Number(a.roles.includes("head_coach"))||a.primaryRole.localeCompare(b.primaryRole));return <Panel className="h-full min-h-0 overflow-y-auto p-4"><Title over="National coaching department" title="Staff"/>{ordered.length?<div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{ordered.map(contract=><div key={contract.staffId} className="rounded-lg border border-border bg-bg p-3"><p className="text-[8px] font-bold uppercase text-accent">{contract.roles.map(role=>role.replaceAll("_"," ")).join(" · ")}</p><p className="mt-1 font-anton text-lg uppercase">{contract.fullName}</p><p className="mt-1 text-[8px] text-text-secondary">Under contract through {contract.endSeason??"rolling"}</p></div>)}</div>:<Empty>No national coaches are currently assigned.</Empty>}</Panel>}
function rank(c:InternationalCareerState,id:string){return Object.entries(c.rankings).sort((a,b)=>b[1]-a[1]).findIndex(x=>x[0]===id)+1}
function LeaderBox({l,n}:{l:string;n:string}){return <div className="min-w-0 rounded border border-white/15 bg-white/10 px-3 py-2 sm:w-36"><small className="text-[8px] text-white/60">{l}</small><p className="truncate text-[9px] font-bold">{n}</p></div>}
function Squad({squad,career,st,player}:{squad:InternationalPlayerProfile[];career:InternationalCareerState;st:InternationalCareerState["teams"][string];player:(id:string)=>void}){
 const groups:[string,(p:InternationalPlayerProfile)=>boolean][]=[
  ["Openers",p=>!!p.isOpener],
  ["Top & middle order",p=>!p.isOpener&&(p.role==="Batsman"||p.role==="WK-Batsman")],
  ["All-rounders",p=>p.role==="All-Rounder"],
  ["Pace bowlers",p=>p.role==="Pace Bowler"],
  ["Spin bowlers",p=>p.role==="Spin Bowler"],
 ];
 return <div className="h-full min-h-0 overflow-y-auto pr-1" aria-label="Team squad">
  <div className="grid grid-cols-1 items-start gap-3 pb-3 md:grid-cols-2 2xl:grid-cols-3">
   {groups.map(([name,includes])=>{
    const members=squad.filter(includes);
    return <Panel key={name} className="min-w-0 p-3 sm:p-4">
     <div className="flex items-end justify-between gap-3 border-b border-border pb-2"><Title title={name}/><span className="shrink-0 font-space-mono text-[9px] text-text-secondary">{members.length} players</span></div>
     <div className="mt-1">{members.map(p=><PRow key={p.id} p={p} s={career.seasonStats[p.id]} badge={p.id===st.captainId?"Captain":st.pendingDebuts[p.id]?"Debut pending":""} click={()=>player(p.id)}/>)}{members.length===0&&<p className="py-3 text-[10px] text-text-secondary">No players in this group</p>}</div>
    </Panel>;
   })}
  </div>
 </div>;
}
function PRow({p,s,badge,click}:{p:InternationalPlayerProfile;s?:InternationalPlayerStats;badge?:string;click:()=>void}){
 const positions=Array.isArray(p.battingPositions)?p.battingPositions:[];
 const status=p.isT20IRetired?"T20I retired":badge;
 return <button onClick={click} className="grid w-full min-w-0 grid-cols-[minmax(0,1fr)_auto] items-center gap-2 border-b border-border/60 py-2.5 text-left last:border-b-0 hover:bg-accent/5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent">
  <div className="min-w-0"><b className="block truncate text-[11px]">{p.name}</b>{status&&<span className={`rounded px-1.5 text-[7px] uppercase ${p.isT20IRetired?"bg-slate-500/15 text-text-secondary":"bg-accent/10 text-accent"}`}>{status}</span>}<p className="truncate text-[9px] text-text-secondary">{p.role} · Age {p.age} · Bats {positions.join("/")||"lower order"}</p></div>
  <span className="shrink-0 text-[9px] font-semibold text-text-primary">{s?.runs??0} R · {s?.wickets??0} W</span>
 </button>;
}
function XI({career,st,player}:{career:InternationalCareerState;st:InternationalCareerState["teams"][string];player:(id:string)=>void}){const xi=st.preferredXI.map(id=>career.profiles[id]),bs=xi.filter(bowler);return <div className="grid gap-4 xl:grid-cols-12"><Panel className="p-5 xl:col-span-8"><Title over="Role-ordered" title="Preferred playing XI"/><div className="mt-3">{xi.map((p,i)=><button key={p.id} onClick={()=>player(p.id)} className="grid w-full grid-cols-[2rem_1fr_8rem_4rem_4rem] border-b border-border/60 py-2.5 text-left text-[9px]"><b>{i+1}</b><b>{p.name}{p.id===st.captainId?" (c)":""}</b><span>{i<2?"Opener":i===2?"No. 3":i<6?"Middle order":bowler(p)?"Bowler":"All-rounder"}</span><span>BAT {p.batting}</span><span>BWL {p.bowling}</span></button>)}</div></Panel><Panel className="p-5 xl:col-span-4"><Title over="Attack plan" title="Bowling roles"/>{[["New ball","powerplayBowling"],["Middle overs","middleOversBowling"],["Death overs","deathBowling"]].map(([n,k])=><div key={n} className="mt-3 rounded border border-border bg-bg p-3"><small className="uppercase text-accent">{n}</small>{[...bs].sort((a,b)=>(b[k as keyof InternationalPlayerProfile] as number)-(a[k as keyof InternationalPlayerProfile] as number)).slice(0,2).map(p=><p key={p.id} className="mt-2 flex justify-between text-[9px]"><span>{p.name}</span><b>{p[k as keyof InternationalPlayerProfile] as number}</b></p>)}</div>)}</Panel></div>}
function CountryStats({id,career,player}:{id:string;career:InternationalCareerState;player:(id:string)=>void}){const rows=Object.entries(career.seasonStats).filter(([pid])=>career.profiles[pid]?.countryId===id);return <div className="grid gap-4 lg:grid-cols-2"><StatList title="Batting" rows={[...rows].sort((a,b)=>b[1].runs-a[1].runs)} career={career} player={player}/><StatList title="Bowling" rows={[...rows].filter(([pid])=>bowler(career.profiles[pid])).sort((a,b)=>b[1].wickets-a[1].wickets)} career={career} player={player} bowl/></div>}

