function Stats({career,player}:{career:InternationalCareerState;player:(id:string)=>void}){const [scope,setScope]=useState("season"),[disc,setDisc]=useState("batting"),[country,setCountry]=useState("all"),[page,setPage]=useState(0),source=scope==="season"?career.seasonStats:career.careerStats,rows=Object.entries(source).filter(([id])=>(country==="all"||career.profiles[id]?.countryId===country)&&(disc==="batting"||bowler(career.profiles[id]))).sort((a,b)=>disc==="batting"?b[1].runs-a[1].runs:b[1].wickets-a[1].wickets),size=11,pages=Math.max(1,Math.ceil(rows.length/size)),safePage=Math.min(page,pages-1),change=(setter:(value:string)=>void,value:string)=>{setter(value);setPage(0)};return <Panel className="flex h-full min-h-0 flex-col overflow-hidden"><div className="flex shrink-0 items-center justify-between gap-3 p-4"><div><Title over={scope==="season"?`IPL ${career.season-1} final → IPL ${career.season} final`:"All international matches"} title="International statistics"/><p className="mt-1 text-[7px] text-text-secondary">Season totals cover the window between consecutive IPL finals.</p></div><div className="flex items-center gap-2">{["season","career"].map(x=><F key={x} a={scope===x} click={()=>change(setScope,x)}>{x}</F>)}{["batting","bowling"].map(x=><F key={x} a={disc===x} click={()=>change(setDisc,x)}>{x}</F>)}<select value={country} onChange={e=>change(setCountry,e.target.value)} className="rounded border border-border bg-bg px-3 py-2 text-[8px]"><option value="all">All countries</option>{INTERNATIONAL_TEAMS.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><Pager page={safePage} pages={pages} setPage={setPage}/></div></div><StatTable rows={rows.slice(safePage*size,safePage*size+size)} start={safePage*size} career={career} player={player} bowl={disc==="bowling"}/></Panel>}
