function Group({name,fs,embedded=false}:{name:string;fs:InternationalFixture[];embedded?:boolean}){const ids=Array.from(new Set(fs.flatMap(f=>[f.teamA,f.teamB]))),rows=ids.map(id=>{const played=fs.filter(f=>f.played&&(f.teamA===id||f.teamB===id)),won=played.filter(f=>f.winner===id).length;return{id,p:played.length,w:won,l:played.length-won,pts:won*2}}).sort((a,b)=>b.pts-a.pts||b.w-a.w),content=<><Title title={name}/>{rows.length?<div className="mt-2 min-w-0"><div className="grid grid-cols-[minmax(0,1fr)_2rem_2rem_2rem_2.5rem] py-1 text-[6px] uppercase text-text-secondary"><span>Team</span><span>P</span><span>W</span><span>L</span><span>Pts</span></div>{rows.map((r,i)=><div key={r.id} className={`grid grid-cols-[minmax(0,1fr)_2rem_2rem_2rem_2.5rem] border-t border-border/60 py-2 text-[8px] ${i<2?"font-bold":""}`}><span className="truncate">{internationalTeamName(r.id)}</span><span>{r.p}</span><span>{r.w}</span><span>{r.l}</span><span className={i<2?"text-accent":""}>{r.pts}</span></div>)}</div>:<Empty>Stage not drawn yet.</Empty>}</>;return embedded?<div className="min-w-0">{content}</div>:<Panel className="min-w-0 p-4">{content}</Panel>}
