function Archive({career}:{career:InternationalCareerState}){const seasons=[{season:career.season,series:career.series,fixtures:career.fixtures,seasonStats:career.seasonStats,profileNames:Object.fromEntries(Object.entries(career.profiles).map(([id,p])=>[id,p.name])),worldCupChampion:career.fixtures.find(f=>f.stage==="final"&&f.played)?.winner,active:true},...[...career.history].reverse().map(h=>({...h,active:false}))],[selected,setSelected]=useState(seasons[0]?.season??career.season),entry=seasons.find(h=>h.season===selected)??seasons[0];if(!entry)return <Empty>No international history is available.</Empty>;const completedSeries=entry.series.filter(s=>s.completed),results=entry.fixtures.filter(f=>f.played).sort((a,b)=>b.date.localeCompare(a.date)),batting=Object.entries(entry.seasonStats??{}).sort((a,b)=>b[1].runs-a[1].runs).slice(0,5),bowling=Object.entries(entry.seasonStats??{}).filter(([id])=>{const p=career.profiles[id];return !p||bowler(p)}).sort((a,b)=>b[1].wickets-a[1].wickets).slice(0,5),name=(id:string)=>entry.profileNames?.[id]??internationalProfileName(career,id),final=entry.fixtures.find(f=>f.stage==="final"&&f.played);return <div className="grid h-full min-h-0 min-w-0 grid-cols-[10rem_minmax(0,1fr)] gap-3"><Panel className="min-h-0 overflow-hidden"><div className="border-b border-border p-3"><Title over="Results archive" title="Seasons"/></div>{seasons.map(h=><button key={`${h.season}-${h.active}`} onClick={()=>setSelected(h.season)} className={`flex w-full justify-between border-b border-border/60 px-3 py-2 text-left text-[8px] ${selected===h.season?"bg-accent/10 text-accent":""}`}><b>{h.season}</b><span>{h.active?"Current":"Complete"}</span></button>)}</Panel><div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_minmax(0,1fr)] gap-3"><Panel className="p-3"><div className="flex items-end justify-between gap-3"><div><p className="font-space-mono text-[6px] font-bold uppercase text-accent">IPL {entry.season-1} final → IPL {entry.season} final</p><h2 className="font-anton text-xl uppercase">{entry.season} international year</h2></div>{entry.worldCupChampion&&<div className="rounded border border-accent/30 bg-accent/10 px-3 py-1.5 text-right"><span className="block text-[6px] uppercase text-text-secondary">World champions</span><b className="text-[9px] text-accent">{internationalTeamName(entry.worldCupChampion)}</b>{final&&<span className="block text-[7px] text-text-secondary">beat {internationalTeamName(final.winner===final.teamA?final.teamB:final.teamA)} · {score(final.scoreA)} to {score(final.scoreB)}</span>}</div>}</div></Panel><div className="grid min-h-0 min-w-0 grid-cols-2 gap-3"><Panel className="min-h-0 min-w-0 overflow-hidden p-3"><Title over="Completed tours" title="Series results"/><div className="mt-1 space-y-1">{completedSeries.slice(0,6).map(s=>{const winner=s.homeWins===s.awayWins?"Drawn":`${internationalTeamName(s.homeWins>s.awayWins?s.hostCountry:s.touringCountry)} won`;return <div key={s.id} className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] gap-2 border-b border-border/60 py-1.5 text-[7px]"><span className="truncate">{internationalTeamName(s.touringCountry)} at {internationalTeamName(s.hostCountry)}</span><b>{winner} {s.homeWins}–{s.awayWins}</b></div>})}{!completedSeries.length&&<p className="text-[8px] text-text-secondary">No completed series yet.</p>}</div></Panel><Panel className="min-h-0 min-w-0 overflow-hidden p-3"><Title over="Year leaders" title="Top performers"/><div className="mt-2 grid grid-cols-2 gap-4"><ArchiveLeaders title="Runs" rows={batting} name={name}/><ArchiveLeaders title="Wickets" rows={bowling} name={name} bowl/></div></Panel></div><Panel className="min-h-0 min-w-0 overflow-hidden p-3"><Title over="Scorecards" title="Latest results"/><div className="mt-2 grid min-w-0 grid-cols-3 gap-2">{results.slice(0,6).map(f=><div key={f.id} className="min-w-0 rounded border border-border bg-bg p-2"><div className="flex justify-between text-[6px] uppercase text-text-secondary"><span>{formatDisplayDate(f.date)}</span><span>{f.stage.replaceAll("-"," ")}</span></div><div className="mt-1 flex justify-between gap-2 text-[7px]"><span className="truncate">{internationalTeamName(f.teamA)}</span><b>{score(f.scoreA)}</b></div><div className="flex justify-between gap-2 text-[7px]"><span className="truncate">{internationalTeamName(f.teamB)}</span><b>{score(f.scoreB)}</b></div><p className="mt-1 truncate text-[6px] font-bold text-accent">{internationalTeamName(f.winner!)} won</p></div>)}</div></Panel></div></div>}
function ArchiveLeaders({title,rows,name,bowl=false}:{title:string;rows:Array<[string,InternationalPlayerStats]>;name:(id:string)=>string;bowl?:boolean}){return <div className="min-w-0"><p className="text-[7px] font-bold uppercase text-text-secondary">{title}</p>{rows.map(([id,s],i)=><div key={id} className="grid grid-cols-[1rem_minmax(0,1fr)_auto] border-b border-border/60 py-2 text-[8px]"><span>{i+1}</span><b className="truncate">{name(id)}</b><b className="text-accent">{bowl?s.wickets:s.runs}</b></div>)}</div>}

function Scorecard({fixture,career,close,player}:{fixture:InternationalFixture;career:InternationalCareerState;close:()=>void;player:(id:string)=>void}){const [i,setI]=useState<0|1>(0),inn=fixture.scorecard?.[i];return <div className="fixed inset-0 z-[110] bg-black/70 p-3 backdrop-blur" onMouseDown={close}><div className="mx-auto flex max-h-full max-w-6xl flex-col overflow-hidden rounded-xl bg-surface" onMouseDown={e=>e.stopPropagation()}><header className="bg-[var(--ink)] p-5 text-white"><div className="flex justify-between"><div><small>{formatDisplayDate(fixture.date)} · {fixture.venue}</small><h2 className="font-anton text-2xl uppercase">{internationalTeamName(fixture.teamA)} v {internationalTeamName(fixture.teamB)}</h2><p className="text-[9px] text-bg/60">{fixture.winner?`${internationalTeamName(fixture.winner)} won`:"Scheduled"} · POTM {fixture.playerOfTheMatchId?internationalProfileName(career,fixture.playerOfTheMatchId):"—"}</p></div><button onClick={close} className="text-2xl">×</button></div><div className="mt-4 grid grid-cols-2 gap-3">{[[fixture.teamA,fixture.scoreA],[fixture.teamB,fixture.scoreB]].map(([id,s])=><div key={String(id)} className="rounded border border-white/15 p-3"><span>{internationalTeamName(String(id))}</span><b className="float-right font-anton text-xl">{score(s as [number,number]|undefined)}</b></div>)}</div></header><div className="flex border-b border-border">{([0,1] as const).map(x=><button key={x} onClick={()=>setI(x)} className={`px-5 py-3 text-[8px] uppercase ${i===x?"border-b-2 border-accent text-accent":""}`}>{internationalTeamName(x?fixture.teamB:fixture.teamA)}</button>)}</div><div className="overflow-y-auto p-5">{inn?<div className="grid gap-6 xl:grid-cols-2"><CardBat rows={inn.batting} career={career} player={player}/><CardBowl rows={inn.bowling} career={career} player={player}/></div>:<Empty>No scorecard yet.</Empty>}</div></div></div>}
function CardBat({rows,career,player}:{rows:Array<[string,number,number,0|1]>;career:InternationalCareerState;player:(id:string)=>void}){return <div><Title title="Batting"/>{rows.map(([id,r,b,d],i)=><button key={id} onClick={()=>player(id)} className="grid w-full grid-cols-[2rem_1fr_3rem_3rem_4rem] border-b border-border/60 py-2 text-left text-[9px]"><span>{i+1}</span><b>{internationalProfileName(career,id)}{d?"":"*"}</b><span>{r}</span><span>{b}</span><span>{b?(r*100/b).toFixed(1):"—"}</span></button>)}</div>}
function CardBowl({rows,career,player}:{rows:Array<[string,number,number,number]>;career:InternationalCareerState;player:(id:string)=>void}){return <div><Title title="Bowling"/>{rows.map(([id,b,r,w])=><button key={id} onClick={()=>player(id)} className="grid w-full grid-cols-[1fr_6rem_3rem_3rem_4rem] border-b border-border/60 py-2 text-left text-[9px]"><b>{internationalProfileName(career,id)}</b><span>{career.profiles[id]?.role}</span><span>{overs(b)}</span><b>{w}</b><span>{b?(r*6/b).toFixed(2):"—"}</span></button>)}</div>}
function LightProfile({p,s,close}:{p:InternationalPlayerProfile;s?:InternationalPlayerStats;close:()=>void}){return <div className="fixed inset-0 z-[120] grid place-items-center bg-black/70 p-5" onMouseDown={close}><Panel className="w-full max-w-xl p-6"><button onClick={close} className="float-right text-2xl">×</button><small className="uppercase text-accent">Lightweight international profile</small><div className="flex flex-wrap items-center gap-2"><h2 className="font-anton text-2xl uppercase">{p.name}</h2>{p.isT20IRetired&&<span className="rounded border border-slate-400/40 bg-slate-500/15 px-2 py-1 font-space-mono text-[7px] font-bold uppercase text-text-secondary">T20I retired</span>}</div><p className="text-[9px] text-text-secondary">{internationalTeamName(p.countryId)} · {p.role} · Age {p.age}</p><div className="mt-5 grid grid-cols-4 gap-2"><Metric v={p.batting} l="Batting"/><Metric v={p.bowling} l="Bowling"/><Metric v={s?.runs??0} l="Runs"/><Metric v={s?.wickets??0} l="Wickets"/></div></Panel></div>}
function SearchView({q,career,team:openTeam,player}:{q:string;career:InternationalCareerState;team:(id:string)=>void;player:(id:string)=>void}){const [page,setPage]=useState(0),x=q.toLowerCase(),ts=INTERNATIONAL_TEAMS.filter(t=>t.name.toLowerCase().includes(x)),ps=Object.values(career.profiles).filter(p=>p.name.toLowerCase().includes(x)),size=12,pages=Math.max(1,Math.ceil(ps.length/size)),safePage=Math.min(page,pages-1);return <Panel className="flex h-full min-h-0 flex-col p-4"><div className="flex shrink-0 items-end justify-between"><Title over="Search" title={`Results for “${q}”`}/><Pager page={safePage} pages={pages} setPage={setPage}/></div><div className="mt-3 grid min-h-0 flex-1 grid-cols-[16rem_minmax(0,1fr)] gap-5"><div className="min-h-0 overflow-hidden"><Title title="Teams"/>{ts.slice(0,10).map(t=><button key={t.id} onClick={()=>openTeam(t.id)} className="flex w-full justify-between border-b border-border py-2 text-[9px]"><b>{t.name}</b><ChevronRight size={13}/></button>)}</div><div className="grid min-h-0 grid-cols-2 content-start gap-x-4"><div className="col-span-2"><Title title="Players"/></div>{ps.slice(safePage*size,safePage*size+size).map(p=><PRow key={p.id} p={p} s={career.seasonStats[p.id]} click={()=>player(p.id)}/>)}</div></div></Panel>}
